const crypto = require('crypto');

// Same scheme as convex/lib/signature.ts: t=<unix>,v1=hmac_sha256("<t>.<METHOD>.<path>.<body>")
function sign(method, path, body) {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const t = Math.floor(Date.now() / 1000);
  const mac = crypto.createHmac('sha256', secret).update(`${t}.${method}.${path}.${body}`).digest('hex');
  return `t=${t},v1=${mac}`;
}

return [{ json: { signature: sign('GET', '/n8n/overdue-loans', '') } }];

// MOCK SENDER. In production, replace the send() body with a real provider call.
// Retries inline and reports per loan, so one bad address can't lose the results of the others.
const { reminderKey, toolName, endDate, daysOverdue, recipient } = $json;

async function send() {
  if ($env.LENDLOOP_SIMULATE_SEND_FAILURE === 'true') {
    throw new Error('Simulated reminder provider outage');
  }
  const [local, domain] = recipient.email.split('@');
  const days = daysOverdue === 1 ? '1 day' : `${daysOverdue} days`;
  console.log(JSON.stringify({
    type: 'lendloop.reminder.sent',
    reminderKey,
    to: `${local.slice(0, 1)}***@${domain}`,
    message: `Hi ${recipient.firstName}, the ${toolName} was due back on ${endDate} (${days} ago). Please return it soon.`,
  }));
}

const MAX_TRIES = 3;
let lastError = 'Unknown error';
for (let attempt = 1; attempt <= MAX_TRIES; attempt++) {
  try {
    await send();
    return { json: { reminderKey, status: 'sent' } };
  } catch (error) {
    lastError = String(error.message).slice(0, 300);
    if (attempt < MAX_TRIES) await new Promise((resolve) => setTimeout(resolve, 2000));
  }
}
return { json: { reminderKey, status: 'failed', error: lastError } };

const crypto = require('crypto');

// Same scheme as convex/lib/signature.ts: t=<unix>,v1=hmac_sha256("<t>.<METHOD>.<path>.<body>")
function sign(method, path, body) {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const t = Math.floor(Date.now() / 1000);
  const mac = crypto.createHmac('sha256', secret).update(`${t}.${method}.${path}.${body}`).digest('hex');
  return `t=${t},v1=${mac}`;
}

const results = $input.all().map((item) => item.json);
const body = JSON.stringify({ executionId: String($execution.id), results });
return [{
  json: {
    body,
    signature: sign('POST', '/n8n/reminder-status', body),
    failed: results.filter((result) => result.status === 'failed').length,
    total: results.length,
  },
}];

// Results are saved by now. Failing the run here sends it to the error workflow, so a reminder
// that couldn't be delivered raises an alert instead of sitting quietly in a table.
const { failed, total } = $('Build Write-back').first().json;
if (failed > 0) throw new Error(`${failed} of ${total} overdue reminders failed to send`);
return [{ json: { total, failed: 0 } }];
